using System;using System.Collections.Generic;using System.Diagnostics;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using ScreenText;
class OneOcrSmoke {
 static readonly BindingFlags Private=BindingFlags.NonPublic|BindingFlags.Instance;
 static T Field<T>(MainForm form,string name){return (T)typeof(MainForm).GetField(name,Private).GetValue(form);}static object Call(MainForm form,string name,params object[] args){return typeof(MainForm).GetMethod(name,Private).Invoke(form,args);}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);}static void Wait(Task task){var clock=Stopwatch.StartNew();while(!task.IsCompleted){Application.DoEvents();Thread.Sleep(10);if(clock.ElapsedMilliseconds>60000)throw new Exception("OCR check timed out");}task.GetAwaiter().GetResult();}
 static string Fixture(string name,string text){var path=Path.Combine(Backend.Base,name+".png");using(var image=new Bitmap(1500,300))using(var graphics=Graphics.FromImage(image))using(var font=new Font("Segoe UI",28)){graphics.Clear(Color.White);graphics.DrawString(text,font,Brushes.Black,24,24);image.Save(path,ImageFormat.Png);}return path;}
 static LocalOcrResult Read(string image,string language,string fallback){var task=OneOcrService.Read(image,language,fallback,CancellationToken.None);Wait(task);return task.Result;}
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string worker=OneOcrService.WorkerPath,backup=worker+".saved",settings=Path.Combine(Backend.Base,"languages.json"),prior=File.Exists(settings)?File.ReadAllText(settings):null;var report=new StringBuilder();try{
  File.WriteAllText(settings,"{\"OcrTag\":\"system\",\"DefaultTarget\":\"ja\",\"Favorites\":[\"ja\",\"el\"]}");var prefs=LanguagePreferences.Load();Check(prefs.OcrTag==OneOcrService.Automatic&&prefs.WindowsOcrTag=="system"&&prefs.DefaultTarget=="ja"&&prefs.Favorites[0]=="ja","Legacy preference migration changed targets or missed auto OCR");prefs.OcrTag="el";prefs.WindowsOcrTag="el";prefs.Save();Check(LanguagePreferences.Load().OcrTag=="el","Explicit Windows language was not retained");prefs.OcrTag=OneOcrService.Automatic;prefs.Save();Check(LanguagePreferences.Load().WindowsOcrTag=="el","Automatic preference lost Windows fallback");
  var probe=OneOcrService.Probe(CancellationToken.None);Wait(probe);string english=Fixture("oneocr-english","Hello world 123. Screenshot text extraction.");
  if(probe.Result.Available){var cases=new Dictionary<string,string>{{"greek","Καλημέρα κόσμε! Hello world 123."},{"korean","안녕하세요. 한국어 텍스트 인식 테스트입니다."},{"japanese","こんにちは。日本語の文字認識テストです。"},{"latin","Überprüfung: Straße, Größe. Français: été, garçon."},{"mixed","Καλημέρα! Hello world.\n안녕하세요. 한국어 테스트입니다.\nこんにちは。日本語のテストです。"}};foreach(var item in cases){var result=Read(Fixture("oneocr-"+item.Key,item.Value),OneOcrService.Automatic,"system");Check(result.Engine=="OneOCR"&&result.Warning==""&&result.Text.Replace("\r","")==item.Value,"OneOCR mismatch for "+item.Key+": "+result.Text);report.AppendLine("PASS: live OneOCR "+item.Key+" exact text.");}
   var blank=Read(Fixture("oneocr-blank",""),OneOcrService.Automatic,"system");Check(blank.Engine=="OneOCR"&&String.IsNullOrEmpty(blank.Text)&&blank.Warning=="","Empty image wrongly triggered fallback");
   using(var form=new MainForm(true)){form.Show();Wait((Task)Call(form,"EnsureOcrLanguages"));Check(Field<ThemeCombo>(form,"ocrLanguage").Items.Cast<OcrOption>().First().Tag==OneOcrService.Automatic,"Automatic is not first choice");Field<LanguagePreferences>(form,"languageSettings").OcrTag=OneOcrService.Automatic;Call(form,"PopulateOcrOptions");Field<ThemeCombo>(form,"extractMode").SelectedIndex=0;Wait((Task)Call(form,"ReadImage",Path.Combine(Backend.Base,"oneocr-mixed.png"),false,true));Check(Field<TextBox>(form,"source").Text.Contains("한국어")&&Field<Label>(form,"status").Text.Contains("OneOCR"),"Workspace did not use real OneOCR");Call(form,"SelectSettingsCategory","Extraction & Translation");var settingsWindow=Field<Form>(form,"settingsWindow");settingsWindow.Show(form);Application.DoEvents();using(var image=new Bitmap(settingsWindow.Width,settingsWindow.Height)){settingsWindow.DrawToBitmap(image,new Rectangle(Point.Empty,settingsWindow.Size));image.Save(Path.Combine(Backend.Base,"OneOCR-settings.png"));}settingsWindow.Hide();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,form.Size));image.Save(Path.Combine(Backend.Base,"OneOCR-main.png"));}form.Close();}
  }else report.AppendLine("SKIP: no locally installed OneOCR; no model downloaded.");
  var explicitResult=Read(english,"en-US","system");Check(explicitResult.Engine=="Windows OCR"&&explicitResult.Text.Contains("Hello world"),"Explicit Windows OCR was replaced");
  File.Move(worker,backup);var missing=Read(english,OneOcrService.Automatic,"en-US");Check(missing.Engine=="Windows OCR"&&missing.Text.Contains("Hello world")&&missing.Warning.Contains("unavailable"),"Missing-helper fallback failed");
  File.Copy(args[1],worker);var mode=Path.Combine(Backend.Base,"oneocr-probe-mode.txt");foreach(string value in new[]{"unavailable","malformed","crash"}){File.WriteAllText(mode,value);var result=Read(english,OneOcrService.Automatic,"en-US");Check(result.Engine=="Windows OCR"&&result.Text.Contains("Hello world")&&result.Warning.Contains("unavailable"),"Local fallback failed: "+value);}
  File.WriteAllText(mode,"empty");var empty=Read(english,OneOcrService.Automatic,"en-US");Check(empty.Engine=="OneOCR"&&empty.Text==""&&empty.Warning=="","Successful empty OCR retried");
  File.WriteAllText(mode,"hang");using(var cancel=new CancellationTokenSource()){var clock=Stopwatch.StartNew();var pending=OneOcrService.Read(english,OneOcrService.Automatic,"en-US",cancel.Token);cancel.CancelAfter(300);bool canceled=false;try{Wait(pending);}catch(OperationCanceledException){canceled=true;}Check(canceled&&clock.ElapsedMilliseconds<4000,"Cancel did not stop worker or incorrectly triggered fallback");}
  File.WriteAllText(mode,"unavailable");bool failed=false;try{Read(english,OneOcrService.Automatic,"zz-ZZ");}catch(InvalidOperationException error){failed=error.Message.Contains("Windows OCR fallback")&&error.Message.Contains("OneOCR");}Check(failed,"Dual failure did not explain both local engines");
  report.AppendLine("PASS: legacy migration; explicit Windows OCR retained; automatic/fallback preferences persist; missing/unavailable/malformed/crashed helper falls back locally with status; empty result does not retry; cancellation kills worker without fallback; both failures remain actionable. No packs installed, no network AI requests, no Microsoft files copied.");File.WriteAllText(args[0],report.ToString());return 0;
 }catch(Exception error){File.WriteAllText(args[0],report+error.ToString());return 1;}finally{if(File.Exists(backup)){if(File.Exists(worker))File.Delete(worker);File.Move(backup,worker);}if(prior==null){if(File.Exists(settings))File.Delete(settings);}else File.WriteAllText(settings,prior);}}
}